TEXT:
block:'if not system " #{cmd} 'SELECT SCHEMA_NAME FROM INFORMATION_SCHEMA.SCHEMATA WHERE SCHEMA_NAME = \"oozie\"' | grep oozie" then
      code = <<-EOF
        CREATE DATABASE oozie;
        GRANT #{privs} ON oozie.* TO 'oozie'@'%' IDENTIFIED BY '#{get_config('mysql-oozie-password')}';
        GRANT #{privs} ON oozie.* TO 'oozie'@'localhost' IDENTIFIED BY '#{get_config('mysql-oozie-password')}';
        FLUSH PRIVILEGES;
      EOF
      IO.popen("mysql -uroot -p#{get_config!('password','mysql-root','os')}", "r+") do |db|
        db.write code
      end
      system "sudo -u oozie /usr/hdp/current/oozie-server/bin/ooziedb.sh create -sqlfile /usr/hdp/current/oozie-server/oozie.sql -run Validate DB Connection"
      self.resolve_notification_references'

code:'mysql -u root -e "DROP USER ''@'localhost';
                          GRANT USAGE ON *.* to '#{get_config('mysql-galera-user')}'@'%' IDENTIFIED BY '#{get_config!('password','mysql-galera','os')}';
                          GRANT ALL PRIVILEGES on *.* TO '#{get_config('mysql-galera-user')}'@'%' IDENTIFIED BY '#{get_config!('password','mysql-galera','os')}';
                          GRANT PROCESS ON *.* to '#{get_config('mysql-check-user')}'@'localhost' IDENTIFIED BY '#{get_config!('password','mysql-check','os')}';
                          UPDATE mysql.user SET password=PASSWORD('#{get_config!('password','mysql-root','os')}') WHERE user='root'; FLUSH PRIVILEGES;
                          UPDATE mysql.user SET host='%' WHERE user='root' and host='localhost';
                          FLUSH PRIVILEGES;"
        EOH'

